import { loadFont } from "@remotion/google-fonts/Outfit";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// DANIEL/XXPAY · gateway de pagamentos global. Motion vertical de 59 s sobre a locução (ElevenLabs, Roberta, 57,9 s, entra em 0,15 s).
// Identidade tirada do próprio app: fundo claro, cartões brancos, botão preto, verde-água do gráfico (#0DA98E), fonte geométrica,
// e o lado preto da tela de login com a grade de quadrados. Problema (moedas, métodos locais, transações soltas) em desenho genérico;
// as telas reais só entram depois da marca. Texto entra e fica parado; o movimento contínuo fica no globo, nas telas e nos objetos.
// Tempos = tempo da palavra na voz; `t` já desconta a entrada da locução.

const { fontFamily: F } = loadFont("normal", { weights: ["400", "500", "600", "700"], subsets: ["latin", "latin-ext"] });

export const XX_FPS = 30;
const LEAD = 0.15;
export const XX_FRAMES = Math.round(59.0 * XX_FPS);

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.5));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const punch = (t: number, ats: number[], amt = 0.04) => 1 + amt * ats.reduce((m, a) => Math.max(m, t >= a ? 1 - k(t, a, 0.32) : 0), 0);

const WHITE = "#FFFFFF";
const INK = "#111214";
const MUTED = "#8B9099";
const LINE = "#E6E8EC";
const BG2 = "#F5F6F8";
const NIGHT = "#0A0A0B";
const TEAL = "#0DA98E";
