const SHADOW = "0 30px 70px rgba(17,18,20,0.10), 0 4px 14px rgba(17,18,20,0.06)";
const SHADOW_D = "0 44px 90px rgba(17,18,20,0.26), 0 6px 18px rgba(17,18,20,0.12)";

// trocas de cena (tempo da voz)
const T2 = 6.2, T6 = 17.75, T7 = 23.35, T8 = 29.2, T9 = 33.1, T10 = 36.85, T11 = 42.75, T12 = 47.5;

const blurIn = (t: number, at: number, out?: number, d = 0.45): React.CSSProperties => {
  const e = k(t, at, d);
  const o = out === undefined ? 0 : lin(t, out, out + 0.2);
  return { opacity: Math.min(1, e * 1.6) * (1 - o), filter: `blur(${((1 - e) * 18 + o * 14).toFixed(1)}px)`, transform: `scale(${(0.9 + 0.1 * e).toFixed(4)})` };
};
type L = [string, number, boolean?];
const Lines: React.FC<{ t: number; items: L[]; size: number; top: number; color?: string; hl?: string; out?: number; weight?: number }> = ({ t, items, size, top, color = INK, hl = TEAL, out, weight = 600 }) => (
