    {items.map(([w, at, h], i) => (
      <div key={i} style={{ fontFamily: F, fontWeight: weight, fontSize: size, lineHeight: 1.1, letterSpacing: "-0.035em", whiteSpace: "nowrap", color: h ? hl : color, paddingBottom: size * 0.06, ...blurIn(t, at, out) }}>{w}</div>
    ))}
  </div>
);

// ───────── globo em linhas (projeção ortográfica) ─────────
type V3 = [number, number, number];
const D = Math.PI / 180;
const ll = (lon: number, lat: number): V3 => [Math.cos(lat * D) * Math.sin(lon * D), Math.sin(lat * D), Math.cos(lat * D) * Math.cos(lon * D)];
const rot = (v: V3, lon0: number, tilt: number): V3 => {
  const c = Math.cos(lon0 * D), s = Math.sin(lon0 * D);
  const x = v[0] * c - v[2] * s, z = v[0] * s + v[2] * c, y = v[1];
  const ct = Math.cos(tilt), st = Math.sin(tilt);
  return [x, y * ct - z * st, y * st + z * ct];
};
const slerp = (a: V3, b: V3, s: number): V3 => {
  const dot = a[0] * b[0] + a[1] * b[1] + a[2] * b[2];
  const w = Math.acos(Math.max(-1, Math.min(1, dot)));
  const sa = Math.sin((1 - s) * w) / Math.sin(w), sb = Math.sin(s * w) / Math.sin(w);
  const h = 1 + 0.2 * Math.sin(Math.PI * s) * Math.min(1, w / 1.2);
  return [(a[0] * sa + b[0] * sb) * h, (a[1] * sa + b[1] * sb) * h, (a[2] * sa + b[2] * sb) * h];
};
type FlagKind = "br" | "eu" | "us" | "jp" | "pt";
export const CITY = { sp: [-46.6, -23.5], lis: [-9.1, 38.7], mia: [-80.2, 25.8], tok: [139.7, 35.7], ber: [13.4, 52.5] } as const;
type Arc = { from: readonly [number, number]; to: readonly [number, number]; a: number; b: number; card?: [number, number]; tail?: number };
type Pin = { at: readonly [number, number]; t0: number; flag?: FlagKind; size?: number; badge?: [string, number] };
const Globe: React.FC<{ t: number; cx: number; cy: number; R: number; lon0: number; tilt?: number; line: string; rim?: string; fill?: string; arcs?: Arc[]; pins?: Pin[]; arcColor?: string }> = ({ t, cx, cy, R, lon0, tilt = 0.32, line, rim, fill, arcs = [], pins = [], arcColor = TEAL }) => {
  const P = (v: V3) => { const r = rot(v, lon0, tilt); return { x: cx + R * r[0], y: cy - R * r[1], z: r[2] }; };
  const paths: string[] = [];
  const seg = (pts: V3[]) => {
    let d = "", on = false;
    for (const p of pts) {
      const q = P(p);
      if (q.z > 0) { d += `${on ? "L" : "M"}${q.x.toFixed(1)} ${q.y.toFixed(1)}`; on = true; } else on = false;
    }
    if (d) paths.push(d);
  };
  for (let lon = -180; lon < 180; lon += 20) seg([...Array(37)].map((_, i) => ll(lon, -90 + i * 5)));
  for (let lat = -60; lat <= 60; lat += 20) seg([...Array(73)].map((_, i) => ll(-180 + i * 5, lat)));
  return (
    <>
      <svg width={1080} height={1920} style={{ position: "absolute", left: 0, top: 0, overflow: "visible" }}>
        <circle cx={cx} cy={cy} r={R} fill={fill ?? "none"} stroke={rim ?? line} strokeWidth={3} />
        {paths.map((d, i) => <path key={i} d={d} fill="none" stroke={line} strokeWidth={2} strokeLinecap="round" />)}
        {arcs.map((a, i) => {
          const p = interpolate(t, [a.a, a.b], [0, 1], { ...cl, easing: INOUT });
          if (p <= 0) return null;
          const A = ll(a.from[0], a.from[1]), B = ll(a.to[0], a.to[1]);
          const n = 48, pts: string[] = [];
          const j0 = a.tail ? Math.max(0, Math.round(n * (p - a.tail))) : 0;
          for (let j = j0; j <= Math.round(n * p); j++) { const q = P(slerp(A, B, j / n)); if (q.z > (a.tail ? 0.05 : -0.05)) pts.push(`${pts.length ? "L" : "M"}${q.x.toFixed(1)} ${q.y.toFixed(1)}`); }
          return <path key={i} d={pts.join("")} fill="none" stroke={arcColor} strokeWidth={6} strokeLinecap="round" strokeDasharray="2 16" />;
        })}
      </svg>
      {pins.map((pn, i) => {
        const q = P(ll(pn.at[0], pn.at[1]));
        const e = pop(t, pn.t0, 0.5);
        if (e <= 0 || q.z < 0.05) return null;
        const s = pn.size ?? 96;
        const ring = ((t - pn.t0) * 0.9) % 1;
        return (
          <div key={i} style={{ position: "absolute", left: q.x - s / 2, top: q.y - s / 2, width: s, height: s, opacity: Math.min(1, e * 2) * Math.min(1, q.z * 4), transform: `scale(${(0.3 + 0.7 * e).toFixed(3)})` }}>
            <div style={{ position: "absolute", inset: -s * 0.5 * ring, borderRadius: "50%", border: `3px solid ${arcColor}`, opacity: 0.6 * (1 - ring) }} />
            {pn.badge && t > pn.badge[1] ? (
              <div style={{ position: "absolute", left: s * 0.55, top: -s * 1.25, width: 150, height: 150, borderRadius: "50%", background: TEAL, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: F, fontWeight: 700, fontSize: 84, color: WHITE, boxShadow: SHADOW_D, opacity: k(t, pn.badge[1], 0.2), transform: `scale(${(0.3 + 0.7 * pop(t, pn.badge[1], 0.5)).toFixed(3)})` }}>{pn.badge[0]}</div>
            ) : null}
            {pn.flag ? <Flag kind={pn.flag} s={s} /> : <div style={{ width: s, height: s, borderRadius: "50%", background: INK, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: SHADOW_D }}><IcoStore s={s * 0.56} c={WHITE} /></div>}
          </div>
        );
      })}
      {arcs.map((a, i) => {
        if (!a.card) return null;
        const p = interpolate(t, a.card, [0, 1], { ...cl, easing: INOUT });
        if (t < a.card[0] - 0.05 || t > a.card[1] + 0.35) return null;
        const q = P(slerp(ll(a.from[0], a.from[1]), ll(a.to[0], a.to[1]), p));
        const land = 1 - k(t, a.card[1], 0.35);
        return (
          <div key={`c${i}`} style={{ position: "absolute", left: q.x - 90, top: q.y - 58, opacity: land, transform: `rotate(${(-12 + 24 * p).toFixed(1)}deg) scale(${(0.6 + 0.4 * Math.sin(Math.PI * Math.min(1, p * 1.2)) + 0.3 * (1 - land)).toFixed(3)})` }}>
            <PayCard w={180} />
          </div>
        );
      })}
    </>
  );
};

