// ───────── cena 2 · os desafios: mercados, moedas, métodos locais, transações soltas (visual genérico) ─────────
const SB = 9.85, SC = 11.55, SD = 13.6;
const win = (t: number, a: number, b: number) => (t < a - 0.05 || t > b + 0.25 ? 0 : k(t, a, 0.3) * (1 - lin(t, b - 0.05, b + 0.18)));
const Desafios: React.FC<{ t: number }> = ({ t }) => {
  const cam = 1 + 0.06 * lin(t, T2, T6);
  // A · novos mercados, novos desafios
  const wa = win(t, T2, SB);
  const flags: [FlagKind, number, number, number][] = [["br", 250, 1130, 7.15], ["eu", 540, 1020, 7.43], ["jp", 830, 1130, 7.75]];
  const hurdles = ["Moedas", "Métodos", "Integração"];
  // B · moedas
  const wb = win(t, SB, SC);
  const SYMS = ["R$", "€", "$", "£", "¥", "R$", "€"];
  const flipT = Math.max(0, t - 10.0) / 0.3;
  const symI = Math.min(SYMS.length - 1, Math.floor(flipT));
  const flipA = (flipT % 1) * 180;
  // C · métodos locais
  const wc = win(t, SC, SD);
  const methods: [string, string][] = [["pix", "Pix"], ["card", "Cartão"], ["boleto", "Boleto"], ["sepa", "SEPA"], ["crypto", "Cripto"], ["wallet", "Carteira digital"]];
  // D · cada transação conectada à operação
  const wd = t >= SD - 0.05 ? k(t, SD, 0.3) : 0;
  const HX = 540, HY = 1250;
  const tiles: [number, number, string, string][] = [[200, 860, "R$", "pix"], [610, 800, "€", "sepa"], [880, 1000, "$", "card"], [160, 1160, "£", "card"], [900, 1330, "€", "wallet"], [220, 1500, "¥", "crypto"], [560, 1620, "R$", "boleto"], [850, 1600, "$", "pix"]];
  const hub = pop(t, 16.53, 0.55);
  return (
    <AbsoluteFill style={{ background: BG2 }}>
      {t < SB + 0.25 ? <Lines t={t} top={240} size={100} out={SB - 0.15} items={[["Novos mercados,", 6.35], ["novos desafios", 8.47, true]]} /> : null}
      {t >= SB - 0.05 && t < SC + 0.25 ? <Lines t={t} top={240} size={130} out={SC - 0.15} items={[["Moedas", 10.03], ["diferentes", 10.45, true]]} /> : null}
      {t >= SC - 0.05 && t < SD + 0.25 ? <Lines t={t} top={240} size={84} out={SD - 0.15} items={[["Formas de pagamento", 11.71], ["locais", 12.67, true]]} /> : null}
      {t >= SD - 0.05 ? <Lines t={t} top={200} size={92} items={[["Conectar", 14.85], ["cada transação", 15.45, true], ["à sua operação", 16.53]]} /> : null}

      <AbsoluteFill style={{ transform: `scale(${cam.toFixed(4)})`, transformOrigin: "540px 1200px" }}>
        {wa > 0 ? (
          <AbsoluteFill style={{ opacity: wa, transform: `scale(${(0.94 + 0.06 * wa).toFixed(4)})` }}>
            <svg width={1080} height={1920} style={{ position: "absolute", left: 0, top: 0 }}>
