  const blinds = (i: number) => interpolate(t, [T11 - 0.3 + i * 0.04, T11 + 0.02 + i * 0.04], [0, 1], { ...cl, easing: INOUT });
  const circ = interpolate(t, [T12 - 0.2, T12 + 0.32], [0, 1], { ...cl, easing: INOUT });
  return (
    <AbsoluteFill style={{ background: WHITE }}>
      {t < T2 + 0.25 ? <AbsoluteFill style={{ transform: `scale(${(1 - 0.06 * sheet).toFixed(4)})` }}><Abertura t={t} /></AbsoluteFill> : null}
