      ) : null}
      {t >= T7 - 0.28 && t < T8 + 0.22 ? (
        <AbsoluteFill style={{ transform: `translateX(${((1 - push) * 1080).toFixed(1)}px) scale(${(1 + 0.25 * back).toFixed(4)})`, opacity: 1 - back }}><Meios t={t} /></AbsoluteFill>
      ) : null}
      {t >= T8 - 0.22 && t < T9 + 0.32 ? (
        <AbsoluteFill style={{ opacity: t < T8 + 0.22 ? back : 1, transform: `scale(${(0.85 + 0.15 * back).toFixed(4)})` }}><Comprador t={t} /></AbsoluteFill>
      ) : null}
      {t >= T9 - 0.02 && t < T10 + 0.24 ? <Painel t={t} /> : null}
      {t >= T9 - 0.32 && t < T9 + 0.32 ? (
        <div style={{ position: "absolute", left: 540 - 1000, top: -500, width: 2000, height: 2920, background: TEAL, transform: `rotate(18deg) translateX(${((band - 0.5) * 2 * 2700).toFixed(1)}px)` }} />
      ) : null}
      {t >= T10 - 0.22 && t < T11 + 0.4 ? (
        <AbsoluteFill style={{ clipPath: `inset(0 ${((1 - split) * 50).toFixed(2)}% 0 ${((1 - split) * 50).toFixed(2)}%)` }}><Crescer t={t} /></AbsoluteFill>
      ) : null}
      {t >= T11 - 0.32 && t < T12 + 0.34 ? (
        <AbsoluteFill style={{ clipPath: t < T11 + 0.3 ? `polygon(${[0, 1, 2, 3, 4, 5].map((i) => { const y0 = i * 320, y1 = y0 + 320 * blinds(i); return `0px ${y0}px, 1080px ${y0}px, 1080px ${y1.toFixed(0)}px, 0px ${y1.toFixed(0)}px, 0px ${y0}px`; }).join(", ")})` : undefined }}><Assinatura t={t} /></AbsoluteFill>
      ) : null}
      {t >= T12 - 0.22 ? (
